rule.example:
// Bad — java.util.Locale written out inline
return s.toLowerCase(java.util.Locale.ROOT);

// Good — imported at the top of the file
import java.util.Locale;
...
return s.toLowerCase(Locale.ROOT);

// Allowed — genuine simple-name collision, suppressed with a reason
import java.util.Date;
...
java.sql.Date sqlDate; // NOPMD - collides with the imported java.util.Date
